B.BN=new A.hA(B.aD,"\ud83d\udcbb","Bilgisayar M\xfchendisli\u011fi","Problemlere farkl\u0131 a\xe7\u0131lardan bak\u0131yor, teknolojiyle \xe7\xf6z\xfcm \xfcretmekten keyif al\u0131yorsun. Kodlar, algoritmalar ve dijital d\xfcnyay\u0131 \u015fekillendirmek sana g\xf6re olabilir.","Gelece\u011fi kodla, \xe7\xf6z\xfcm\xfcn\xfc yarat!")
B.BS=new A.hA(B.aP,"\ud83e\uddea","Kimya M\xfchendisli\u011fi","Merak ediyor, deniyor, g\xf6zlemliyor ve \u201cneden?\u201d sorusunun pe\u015finden gidiyorsun. Maddelerin d\xfcnyas\u0131n\u0131 ke\u015ffetmek ve yeni \xe7\xf6z\xfcmler \xfcretmek sana g\xf6re olabilir.","Ke\u015ffet, d\xf6n\xfc\u015ft\xfcr, gelece\u011fi \xfcret!")
B.BT=new A.hA(B.ak,"\ud83c\udf31","\xc7evre M\xfchendisli\u011fi","Do\u011fay\u0131, kaynaklar\u0131 ve s\xfcrd\xfcr\xfclebilir ya\u015fam\u0131 \xf6nemsiyor; problemlere b\xfct\xfcnsel \xe7\xf6z\xfcmler bulmay\u0131 seviyorsun.","Daha iyi bir gelecek i\xe7in d\xfcnyay\u0131 d\xf6n\xfc\u015ft\xfcr!")
B.BO=new A.hA(B.av,"\u2699\ufe0f","Makine M\xfchendisli\u011fi","Bir \u015feyin nas\u0131l \xe7al\u0131\u015ft\u0131\u011f\u0131n\u0131 merak ediyor, par\xe7alar\u0131 bir araya getirerek yeni \u015feyler tasarlamaktan ho\u015flan\u0131yorsun.","Tasarla, \xfcret, harekete ge\xe7ir!")
B.BP=new A.hA(B.al,"\u26a1","Elektrik-Elektronik M\xfchendisli\u011fi","Enerji, teknoloji ve elektronik sistemlerin nas\u0131l \xe7al\u0131\u015ft\u0131\u011f\u0131n\u0131 merak ediyorsun. Karma\u015f\u0131k sistemleri \xe7\xf6zmek ve yeni teknolojiler geli\u015ftirmek sana g\xf6re olabilir.","Enerjini gelece\u011fe ba\u011fla!")
B.BQ=new A.hA(B.am,"\ud83d\udcca","End\xfcstri M\xfchendisli\u011fi","B\xfcy\xfck resmi g\xf6rmeyi, sistemleri analiz etmeyi ve i\u015fleri daha iyi, h\u0131zl\u0131 ve verimli hale getirmeyi seviyorsun.","Sistemi g\xf6r, \xe7\xf6z\xfcm\xfc geli\u015ftir!")
B.BR=new A.hA(B.aY,"\ufe0f","\u0130n\u015faat M\xfchendisli\u011fi","Bir fikrin ger\xe7e\u011fe d\xf6n\xfc\u015fmesini g\xf6rmek, sa\u011flam ve g\xfcvenli yap\u0131lar tasarlamak ilgini \xe7ekiyor.","Sa\u011flam temellerle gelece\u011fi in\u015fa et!")
